<template>
  <div class="flex flex-col gap-2">
    <div
      class="aspect-square relative overflow-hidden rounded-lg border-2 border-dashed border-border bg-muted/30 flex flex-col items-center justify-center gap-3 p-4 transition-colors"
      :class="[containerClass, disabled ? 'opacity-60' : 'hover:bg-muted/50']"
    >
      <img
        v-if="displayUrl"
        :src="displayUrl"
        :alt="fileName ?? 'Uploaded image'"
        class="absolute inset-0 h-full w-full object-cover"
      />
      <template v-else-if="!isUploading">
        <ImagePlus class="h-10 w-10 text-muted-foreground" />
        <p class="text-xs text-muted-foreground text-center">{{ helperText }}</p>
      </template>

      <div v-if="isUploading" class="absolute inset-0 flex items-center justify-center bg-black/40">
        <Spinner class="w-8 h-8 fill-card text-card stroke-card" />
      </div>

      <button
        v-if="displayUrl && !isUploading"
        type="button"
        :disabled="disabled"
        class="absolute top-2 right-2 bg-slate-500/70 rounded-md p-1 z-10 disabled:cursor-not-allowed disabled:opacity-50"
        aria-label="Remove uploaded image"
        @click.stop.prevent="onRemoveClick"
      >
        <XIcon class="w-4 h-4 stroke-slate-100 hover:stroke-slate-800" />
      </button>

      <input
        ref="fileInput"
        type="file"
        :accept="accept"
        :disabled="disabled || isUploading"
        :aria-label="ariaLabel"
        class="absolute inset-0 opacity-0 cursor-pointer disabled:cursor-not-allowed"
        @input.stop
        @change.stop="onFileChange"
      />
    </div>
    <p v-if="fileName" class="text-xs text-muted-foreground">{{ fileName }}</p>

    <ImageCropDialog
      v-if="cropSrc"
      v-model:open="isDialogOpen"
      :src="cropSrc"
      :file-name="pendingFileName"
      :mime-type="pendingMimeType"
      :circle="circle"
      @apply="onCropApply"
      @cancel="onCropCancel"
    />
  </div>
</template>

<script setup lang="ts">
import { ImagePlus, XIcon } from 'lucide-vue-next';
import { Spinner } from '~/assets/icons';
import ImageCropDialog from '~/components/common/ImageCropDialog.vue';

interface Props {
  modelValue?: string;
  previewUrl?: string;
  maxSizeMb?: number;
  allowSvg?: boolean;
  disabled?: boolean;
  helperText?: string;
  ariaLabel?: string;
  containerClass?: string;
  // Show a circular guide in the crop dialog (for images displayed as circles, e.g. avatars).
  circle?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: undefined,
  previewUrl: undefined,
  maxSizeMb: 10,
  allowSvg: false,
  disabled: false,
  circle: false,
  helperText: 'Click to upload and crop a square image (PNG or JPG)',
  ariaLabel: 'Upload image',
  containerClass: 'sm:min-w-[10rem] max-w-[20rem]',
});

interface Emits {
  (e: 'update:modelValue', value: string | undefined): void;
  (e: 'update:uploading', value: boolean): void;
}
const emit = defineEmits<Emits>();

const RASTER_TYPES = ['image/png', 'image/jpeg'];
const SVG_TYPE = 'image/svg+xml';

const accept = computed(() => (props.allowSvg ? [...RASTER_TYPES, SVG_TYPE] : RASTER_TYPES).join(','));

const displayUrl = ref<string | undefined>(props.previewUrl);
const fileName = ref<string | undefined>(undefined);
const isUploading = ref(false);
const fileInput = ref<HTMLInputElement | null>(null);

const isDialogOpen = ref(false);
const cropSrc = ref<string | undefined>(undefined);
const pendingFileName = ref<string | undefined>(undefined);
const pendingMimeType = ref<string | undefined>(undefined);

const { uploadFileData } = useUploadFile();

watch(
  () => props.previewUrl,
  (value) => {
    displayUrl.value = value;
  }
);

watch(
  () => props.modelValue,
  (value) => {
    if (!value) {
      displayUrl.value = undefined;
      fileName.value = undefined;
    }
  }
);

function resetInput() {
  if (fileInput.value) fileInput.value.value = '';
}

function isAcceptedType(file: File): boolean {
  if (props.allowSvg && file.type === SVG_TYPE) return true;
  return RASTER_TYPES.includes(file.type);
}

function onFileChange(event: Event) {
  const target = event.target as HTMLInputElement;
  const file = target.files?.[0];
  if (!file) return;

  if (!isAcceptedType(file)) {
    showToastError(
      props.allowSvg
        ? 'Unsupported file type. Allowed types: JPEG, JPG, PNG, SVG.'
        : 'Unsupported file type. Allowed types: JPEG, JPG, PNG.'
    );
    resetInput();
    return;
  }

  const maxBytes = props.maxSizeMb * 1024 * 1024;
  if (file.size > maxBytes) {
    showToastError(`File size should not exceed ${props.maxSizeMb} MB`);
    resetInput();
    return;
  }

  // SVG (logos only) is a vector image — it has no fixed raster size to crop and the cropper
  // renders it blank. Upload it as-is; the preview comes from the uploaded URL (an <img>
  // renders SVG directly), matching the pre-cropper behaviour.
  if (props.allowSvg && file.type === SVG_TYPE) {
    void uploadFile(file);
    resetInput();
    return;
  }

  // Raster image — let the user crop it to a square first.
  pendingFileName.value = file.name;
  pendingMimeType.value = file.type;
  if (cropSrc.value) URL.revokeObjectURL(cropSrc.value);
  cropSrc.value = URL.createObjectURL(file);
  isDialogOpen.value = true;
  resetInput();
}

async function onCropApply(file: File) {
  await uploadFile(file);
  closeDialog();
}

function onCropCancel() {
  closeDialog();
}

function closeDialog() {
  isDialogOpen.value = false;
  if (cropSrc.value) {
    URL.revokeObjectURL(cropSrc.value);
    cropSrc.value = undefined;
  }
  pendingFileName.value = undefined;
  pendingMimeType.value = undefined;
}

async function uploadFile(file: File) {
  isUploading.value = true;
  emit('update:uploading', true);
  try {
    const response = await uploadFileData({ file });
    displayUrl.value = response.public_url;
    fileName.value = file.name;
    emit('update:modelValue', response.private_url);
  } catch {
    showToastError('Failed to upload file');
    displayUrl.value = undefined;
    fileName.value = undefined;
    emit('update:modelValue', undefined);
  } finally {
    isUploading.value = false;
    emit('update:uploading', false);
  }
}

function onRemoveClick() {
  displayUrl.value = undefined;
  fileName.value = undefined;
  emit('update:modelValue', undefined);
  resetInput();
}
</script>
