<template>
  <Dialog :open="open" @update:open="onOpenChange">
    <DialogContent class="max-w-2xl">
      <DialogHeader>
        <DialogTitle>Crop Image</DialogTitle>
        <DialogDescription>Drag and zoom to position your image. It will be cropped to a square.</DialogDescription>
      </DialogHeader>

      <div class="crop-area relative mx-auto aspect-square w-full max-w-[34rem] overflow-hidden rounded-lg bg-muted">
        <Cropper
          ref="cropperRef"
          class="h-full w-full"
          :src="src"
          :stencil-size="stencilSize"
          :stencil-props="{ handlers: {}, lines: {}, movable: false, resizable: false }"
          image-restriction="stencil"
        />
        <div
          v-if="circle"
          data-testid="crop-circle-overlay"
          class="pointer-events-none absolute inset-0 z-10 rounded-full shadow-[0_0_0_9999px_rgba(0,0,0,0.45)]"
        />
      </div>

      <DialogFooter class="gap-2">
        <Button type="button" variant="outline" aria-label="Cancel crop" @click="onCancel">Cancel</Button>
        <Button type="button" :loading="isProcessing" aria-label="Apply crop" @click="onApply">Apply</Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { Cropper } from 'vue-advanced-cropper';
import 'vue-advanced-cropper/dist/style.css';

interface Props {
  open: boolean;
  src: string;
  fileName?: string;
  // Source mime type, preserved on the cropped output so a PNG keeps its transparency
  // (and the output File's extension matches its bytes). Falls back to JPEG.
  mimeType?: string;
  // Overlay a circular guide inside the square crop area. The output stays square;
  // this only previews how the image will look where it is displayed as a circle.
  circle?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  fileName: 'avatar.jpg',
  mimeType: 'image/jpeg',
  circle: false,
});

// Fixed, centered square stencil that fills the available area. The user pans and
// zooms the image behind it instead of resizing a selection box — this removes the
// stencil's border/handle lines and keeps a circle overlay perfectly aligned.
function stencilSize({ boundaries }: { boundaries: { width: number; height: number } }) {
  const size = Math.min(boundaries.width, boundaries.height);
  return { width: size, height: size };
}

interface Emits {
  (e: 'update:open', value: boolean): void;
  (e: 'apply', file: File): void;
  (e: 'cancel'): void;
}
const emit = defineEmits<Emits>();

const MAX_OUTPUT_PX = 1024;

const cropperRef = ref<InstanceType<typeof Cropper> | null>(null);
const isProcessing = ref(false);

function onOpenChange(value: boolean) {
  if (!value) onCancel();
}

function onCancel() {
  emit('update:open', false);
  emit('cancel');
}

async function onApply() {
  const canvas = cropperRef.value?.getResult?.()?.canvas as HTMLCanvasElement | undefined;
  if (!canvas) {
    showToastError('Failed to process image');
    return;
  }

  isProcessing.value = true;
  try {
    const output = scaleCanvas(canvas, MAX_OUTPUT_PX);
    // Preserve the source format (quality is honoured for JPEG, ignored for lossless PNG).
    const blob = await canvasToBlob(output, props.mimeType, 0.9);
    emit('apply', new File([blob], props.fileName, { type: props.mimeType }));
    emit('update:open', false);
  } catch {
    showToastError('Failed to process image');
  } finally {
    isProcessing.value = false;
  }
}

function scaleCanvas(canvas: HTMLCanvasElement, maxPx: number): HTMLCanvasElement {
  const longEdge = Math.max(canvas.width, canvas.height);
  if (longEdge <= maxPx) return canvas;
  const scaled = document.createElement('canvas');
  scaled.width = Math.round((canvas.width / longEdge) * maxPx);
  scaled.height = Math.round((canvas.height / longEdge) * maxPx);
  scaled.getContext('2d')?.drawImage(canvas, 0, 0, scaled.width, scaled.height);
  return scaled;
}

function canvasToBlob(canvas: HTMLCanvasElement, type: string, quality: number): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error('Canvas is empty'))), type, quality);
  });
}
</script>

<style scoped>
/* Replace the cropper's default dark background/foreground so no black areas show. */
.crop-area :deep(.vue-advanced-cropper__background),
.crop-area :deep(.vue-advanced-cropper__foreground) {
  background: transparent;
}
</style>
